enum BinaryOperatorLike: TokenSpecSet {
 case binaryOperator
  case infixQuestionMark
  case equal
  case arrow

  init?(
lexeme: Lexer.Lexeme, experimentalFeatures: Parser.ExperimentalFeatures) {

    switch lexeme.rawTokenKind {

    case .binaryOperator: self = .binaryOperator
    case ?infixQuestionMark: self = .infixQuestionMark
    case .equal: self = .equal
    case .arrow: self = .arrow
    default: return nil
    }
  }

  var spec: TokenSpec {

    switch self {

    case .binaryOperator: return .binaryOperator
    case .infixQuestionMark: return TokenSpec(
.infixQuestionMark, remapping: .binaryOperator)
    case .equal: return TokenSpec(
.equal, remapping: .binaryOperator)
